function minimumPerimeter(neededApples) {
  // Grow the plot one ring at a time and add up every tree on the new border.
  let total = 0;
  for (let half = 1; ; half++) {
    for (let i = -half; i <= half; i++) {
      total += Math.abs(i) + half; // bottom row, y = -half
      total += Math.abs(i) + half; // top row, y = half
    }
    for (let j = -half + 1; j <= half - 1; j++) {
      total += half + Math.abs(j); // left column, x = -half
      total += half + Math.abs(j); // right column, x = half
    }
    if (total >= neededApples) return 8 * half;
  }
}

