function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const apples = half => 2 * half * (half + 1) * (2 * half + 1);
  const r = rand();
  if (size === 'small') {
    // Values just around a plot's exact total are where off-by-one errors show.
    if (r < 0.5) {
      const total = apples(1 + pick(60));
      return [Math.max(1, total + pick(3) - 1)];
    }
    if (r < 0.75) return [1 + pick(200)];
    return [1 + pick(3000000)];
  }
  const top = Math.floor(Math.cbrt(1e15 / 4)) - 1;
  if (r < 0.2) return [1e15];
  if (r < 0.6) {
    const total = apples(top - pick(20000));
    return [Math.min(1e15, total + pick(3) - 1)];
  }
  return [1e14 + Math.floor(rand() * 9e14)];
}
